const response = await fetch('https://api.aimlapi.com/v2/video/generations', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer <YOUR_AIMLAPI_KEY>',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
  "model": "minimax/h3-max-recast",
  "video_url": "https://example.com/input.jpg",
  "reference_image_urls": [
    "https://example.com/input.jpg"
  ],
  "prompt": "Describe what you want the model to generate."
}),
});

console.log(await response.json());

import requests

response = requests.post(
    "https://api.aimlapi.com/v2/video/generations",
    headers={
        "Authorization": "Bearer <YOUR_AIMLAPI_KEY>",
        "Content-Type": "application/json",
    },
    json={'model': 'minimax/h3-max-recast', 'video_url': 'https://example.com/input.jpg', 'reference_image_urls': ['https://example.com/input.jpg'], 'prompt': 'Describe what you want the model to generate.'},
)

print(response.json())
